<template><section id='contact' class='container py-24'><div class='card p-8'><h2 class='text-2xl font-bold'>Contacto</h2><form class='mt-6 grid md:grid-cols-2 gap-4' @submit.prevent='submit'><input v-model='name' type='text' placeholder='Nombre' class='card p-3' required><input v-model='email' type='email' placeholder='Email' class='card p-3' required><textarea v-model='message' rows='5' placeholder='Mensaje' class='card p-3 md:col-span-2' required></textarea><button class='btn-primary md:col-span-2'>Enviar</button></form></div></section></template><script setup>import axios from 'axios';import { ref } from 'vue';const name=ref(''), email=ref(''), message=ref('');const API_BASE = import.meta.env.VITE_API_BASE || 'http://localhost:3000';async function submit(){try{await axios.post(`${API_BASE}/api/contact`,{name:name.value,email:email.value,message:message.value});alert('¡Mensaje enviado! Te responderemos pronto.');name.value='';email.value='';message.value='';}catch(e){alert('No se pudo enviar. Intenta más tarde.');console.error(e)}};</script>